-- 设置数据库字符集
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ============================================
-- 删除数据库（如果存在）
-- ============================================
DROP DATABASE IF EXISTS `platform`;

-- ============================================
-- 创建数据库
-- ============================================
CREATE DATABASE IF NOT EXISTS `platform` DEFAULT CHARACTER SET utf8mb4 DEFAULT COLLATE utf8mb4_unicode_ci;

USE `platform`;

DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `user_sessions`;
DROP TABLE IF EXISTS `clients`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `product_assignments`;
DROP TABLE IF EXISTS `ad_data`;
DROP TABLE IF EXISTS `ad_data_archive`;
DROP TABLE IF EXISTS `scheduled_tasks`;
DROP TABLE IF EXISTS `token_blacklist`;
DROP TABLE IF EXISTS `user_audit_logs`;

CREATE TABLE IF NOT EXISTS `users` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名称(登录名称)',
  `hashed_password` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户Hash密码',
  `full_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户全名',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户邮箱',
  `role` enum('admin','client') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'client' COMMENT '用户角色(ADMIN 管理员 / CLIENT 客户)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否激活',
  `login_restricted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否限制登录',
  `login_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '登录提示消息',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_users_username` (`username`) USING BTREE,
  UNIQUE KEY `uq_users_email` (`email`) USING BTREE,
  KEY `idx_username` (`username`),
  KEY `idx_email` (`email`),
  FULLTEXT KEY `ft_users_search` (`username`,`full_name`,`email`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户表';

LOCK TABLES `users` WRITE;
UNLOCK TABLES;

CREATE TABLE IF NOT EXISTS `user_sessions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `token_jti` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JWT令牌ID（jti）',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录IP地址',
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户代理（浏览器信息）',
  `device_info` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备信息（移动端/桌面端）',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录位置（可选，通过IP解析）',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否活跃',
  `last_activity` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '最后活动时间',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（登录时间）',
  `expires_at` datetime(6) NOT NULL COMMENT '过期时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_user_sessions_token_jti` (`token_jti`) USING BTREE,
  KEY `idx_session_user_active` (`user_id`,`is_active`),
  KEY `idx_session_expires` (`expires_at`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_token_jti` (`token_jti`),
  KEY `idx_ip_address` (`ip_address`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_last_activity` (`last_activity`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户会话表';

CREATE TABLE IF NOT EXISTS `clients` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '客户ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司名称',
  `contact_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '公司地址',
  `allowed_ips` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'IP白名单，多个IP用逗号分隔，为空则不限制',
  `key` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户唯一标识UUID',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否激活',
  `api_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否允许API访问（开启后允许客户通过API查询产品和广告数据，并显示API对接菜单）',
  `password_change_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否允许客户修改密码（开启后客户可以修改自己的密码）',
  `chat_id` bigint DEFAULT NULL COMMENT '15位聊天ID',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_clients_key` (`key`) USING BTREE,
  UNIQUE KEY `chat_id` (`chat_id`),
  KEY `idx_client_user` (`user_id`),
  KEY `idx_clients_key` (`key`),
  FULLTEXT KEY `ft_clients_search` (`company_name`,`contact_person`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `fk_clients_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='客户表';

LOCK TABLES `clients` WRITE;
UNLOCK TABLES;

CREATE TABLE IF NOT EXISTS `products` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `client_id` int NOT NULL COMMENT '客户ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `ecpm_deduct_ratio` float NOT NULL DEFAULT '0' COMMENT 'eCPM减扣比例',
  `revenue_deduct_ratio` float NOT NULL DEFAULT '0' COMMENT '收益减扣比例',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否激活',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_product_client` (`client_id`),
  KEY `idx_product_name` (`name`),
  FULLTEXT KEY `ft_products_name` (`name`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `fk_products_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='产品表';

LOCK TABLES `products` WRITE;
UNLOCK TABLES;


CREATE TABLE IF NOT EXISTS `product_assignments` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '分配记录ID',
  `product_id` int NOT NULL COMMENT '产品ID',
  `client_id` int NOT NULL COMMENT '客户ID',
  `start_date` date NOT NULL COMMENT '分配开始日期',
  `end_date` date DEFAULT NULL COMMENT '分配结束日期（NULL表示当前有效）',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_product_assignments_product` (`product_id`),
  KEY `idx_product_assignments_client` (`client_id`),
  KEY `idx_product_assignments_date` (`product_id`,`start_date`,`end_date`),
  KEY `idx_product_assignments_active` (`product_id`,`end_date`),
  CONSTRAINT `fk_product_assignments_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_product_assignments_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='产品分配历史表';

LOCK TABLES `product_assignments` WRITE;
UNLOCK TABLES;

CREATE TABLE IF NOT EXISTS `ad_data` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '广告数据ID',
  `date` datetime NOT NULL COMMENT '数据日期',
  `product_id` int NOT NULL COMMENT '产品ID',
  `request_count` int NOT NULL DEFAULT '0' COMMENT '请求数',
  `match_count` int NOT NULL DEFAULT '0' COMMENT '匹配数',
  `display_count` int NOT NULL DEFAULT '0' COMMENT '展示数',
  `click_count` int NOT NULL DEFAULT '0' COMMENT '点击数',
  `ecpm_before_deduct` float NOT NULL DEFAULT '0' COMMENT 'eCPM未减扣',
  `ecpm_after_deduct` float NOT NULL DEFAULT '0' COMMENT 'eCPM已减扣',
  `revenue_before_deduct` float NOT NULL DEFAULT '0' COMMENT '收益未减扣',
  `revenue_after_deduct` float NOT NULL DEFAULT '0' COMMENT '收益已减扣',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_ad_data_date_product` (`date`,`product_id`) USING BTREE,
  KEY `idx_ad_data_date` (`date`),
  KEY `idx_ad_data_product` (`product_id`),
  KEY `idx_ad_data_date_product` (`date`,`product_id`),
  CONSTRAINT `fk_ad_data_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='广告数据表';

LOCK TABLES `ad_data` WRITE;
UNLOCK TABLES;

CREATE TABLE IF NOT EXISTS `ad_data_archive` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '广告数据ID',
  `date` datetime NOT NULL COMMENT '数据日期',
  `product_id` int NOT NULL COMMENT '产品ID',
  `request_count` int NOT NULL DEFAULT '0' COMMENT '请求数',
  `match_count` int NOT NULL DEFAULT '0' COMMENT '匹配数',
  `display_count` int NOT NULL DEFAULT '0' COMMENT '展示数',
  `click_count` int NOT NULL DEFAULT '0' COMMENT '点击数',
  `ecpm_before_deduct` float NOT NULL DEFAULT '0' COMMENT 'eCPM未减扣',
  `ecpm_after_deduct` float NOT NULL DEFAULT '0' COMMENT 'eCPM已减扣',
  `revenue_before_deduct` float NOT NULL DEFAULT '0' COMMENT '收益未减扣',
  `revenue_after_deduct` float NOT NULL DEFAULT '0' COMMENT '收益已减扣',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=ARCHIVE DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='广告数据归档表';

CREATE TABLE IF NOT EXISTS `scheduled_tasks` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '定时任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称（唯一）',
  `last_run_time` datetime(6) DEFAULT NULL COMMENT '上次执行时间',
  `is_running` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否正在执行',
  `last_run_pid` int DEFAULT NULL COMMENT '上次执行的进程ID',
  `last_run_host` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上次执行的服务器主机名',
  `run_count` int NOT NULL DEFAULT '0' COMMENT '执行次数',
  `success_count` int NOT NULL DEFAULT '0' COMMENT '成功次数',
  `error_count` int NOT NULL DEFAULT '0' COMMENT '失败次数',
  `last_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '最后一次错误信息',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
  `cron_expression` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Cron表达式',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '任务描述',
  `function_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行函数路径（例如：app.scheduler_module.tasks.simple_task.simple_info_task）',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_scheduled_tasks_task_name` (`task_name`) USING BTREE,
  KEY `idx_scheduled_task_name` (`task_name`),
  KEY `idx_scheduled_task_is_running` (`is_running`),
  KEY `idx_scheduled_task_is_active` (`is_active`),
  FULLTEXT KEY `ft_tasks_search` (`task_name`,`description`) /*!50100 WITH PARSER `ngram` */ 
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='定时任务执行记录表';

LOCK TABLES `scheduled_tasks` WRITE;
UNLOCK TABLES;

CREATE TABLE IF NOT EXISTS `token_blacklist` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '黑名单ID',
  `token_jti` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JWT令牌ID（jti）',
  `user_id` int NOT NULL COMMENT '用户ID',
  `revoked_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '撤销时间',
  `expires_at` datetime(6) NOT NULL COMMENT 'Token过期时间',
  `reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '撤销原因（用户退出、强制退出等）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_token_blacklist_token_jti` (`token_jti`) USING BTREE,
  KEY `idx_blacklist_user` (`user_id`),
  KEY `idx_blacklist_expires` (`expires_at`),
  KEY `idx_token_jti` (`token_jti`),
  KEY `idx_revoked_at` (`revoked_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Token黑名单表';

CREATE TABLE IF NOT EXISTS `user_audit_logs` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `user_id` int DEFAULT NULL COMMENT '用户ID（可为空，记录未登录访问）',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名（冗余字段，便于查询）',
  `action_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：LOGIN, LOGOUT, CREATE, UPDATE, DELETE, VIEW, ACCESS等',
  `resource_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源类型：USER, CLIENT, PRODUCT, AD_DATA, SCHEDULED_TASK等',
  `resource_id` int DEFAULT NULL COMMENT '资源ID',
  `resource_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源名称（冗余字段，便于查询）',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP地址',
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户代理（浏览器信息）',
  `request_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP请求方法',
  `request_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求路径',
  `request_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '请求参数（JSON格式，不包含敏感信息）',
  `status_code` int DEFAULT NULL COMMENT 'HTTP状态码',
  `success` tinyint(1) NOT NULL DEFAULT '1' COMMENT '操作是否成功',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '错误信息（如果失败）',
  `details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '详细信息（JSON格式）',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_audit_log_user_id` (`user_id`),
  KEY `idx_audit_log_username` (`username`),
  KEY `idx_audit_log_action_type` (`action_type`),
  KEY `idx_audit_log_resource_type` (`resource_type`),
  KEY `idx_audit_log_ip_address` (`ip_address`),
  KEY `idx_audit_log_request_path` (`request_path`),
  KEY `idx_audit_log_success` (`success`),
  KEY `idx_audit_log_created_at` (`created_at`),
  KEY `idx_audit_log_user_action` (`user_id`,`action_type`),
  KEY `idx_audit_log_resource` (`resource_type`,`resource_id`),
  CONSTRAINT `fk_user_audit_logs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=179 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户操作日志表（审计日志）';